struct Resource { int id; ~Resource() { /* Cleanup */ } };

// Unique Ownership
std::unique_ptr<Resource> u_ptr = std::make_unique<Resource>(1);
u_ptr->id = 42;

// Ownership transfer required (no copying allowed)
std::unique_ptr<Resource> u_ptr2 = std::move(u_ptr);
// u_ptr is now nullptr

Resource* raw_ptr = u_ptr2.get(); // Access raw pointer

// Resource deleted automatically when u_ptr2 goes out of scope.

// Shared Ownership (Reference Counting)
std::shared_ptr<Resource> s_ptr1 = std::make_shared<Resource>(2);

std::shared_ptr<Resource> s_ptr2 = s_ptr1; // Copying is allowed

long count = s_ptr1.use_count(); // count == 2

// Resource deleted only when the last shared_ptr goes out of scope.

// Weak Pointers (breaking circular references)
std::weak_ptr<Resource> w_ptr = s_ptr1;

if (auto locked = w_ptr.lock()) {
    locked->id = 99; // Safe access if resource still exists
}
